let toastTimer;
function persist(){localStorage.setItem('kernel-studio-v1',JSON.stringify({version:1,pid:state.pid,name:state.name,address:state.address,tid:state.tid,bookmarks:state.bookmarks}));}
function toast(text,error=false){const box=$('#toast');box.textContent=text;box.className=error?'error':'';box.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>box.style.display='none',4500);$('#footer-status').textContent=text;}
async function api(path,data,method){const response=await fetch(path,{method:method || (data===undefined?'GET':'POST'),headers:{...(data===undefined?{}:{'Content-Type':'application/json'}),'X-Kernel-Priority':data?._background?'live':'manual'},body:data===undefined?undefined:JSON.stringify(data)});let result;try{result=JSON.parse(await response.text(),(key,value,context)=>typeof value==='number' && Number.isInteger(value) && !Number.isSafeInteger(value) && context?.source?context.source:value);}catch{throw Error(`응답을 읽을 수 없습니다 (${response.status})`);}if(!response.ok)throw Error(typeof result.detail==='string'?result.detail:JSON.stringify(result));return result;}
function selectTarget(pid,name){if(state.busy)return toast('현재 요청이 완료된 후 대상을 변경하세요',true);if(state.pid!==Number(pid)){state.address='';state.forms={};state.lastId='';}window.ProductivitySuite?.reset();clearVisits();window.MemoryWorkbench?.reset();window.WideMemory?.reset();window.MemoryAllocation?.reset();window.ScanWorkbench?.reset();window.DisassemblyWorkbench?.reset();window.DllWorkbench?.reset(Number(pid));state.pid=Number(pid);state.name=name;state.tid='';persist();updateTarget();$('#process-dialog').close();state.results={};toast(`${name} · PID ${pid} 선택`);render();}
function updateTarget(){$('#target-summary').textContent=state.pid?`${state.name || '프로세스'} · PID ${state.pid}`:'선택된 프로세스 없음';$('#global-address').value=state.address;$('#global-tid').value=state.tid;}
function pageInfo(){return PAGES.find(p=>p[0]===state.page);}
function currentOperation(){return state.operations[state.page] || pageInfo()[3][0];}
function navigate(page,operation,save=true){if(state.page==='allocation')window.MemoryAllocation?.stash();if(state.page==='wide')window.WideMemory?.stash();if(['structures','projects','changes','timeline'].includes(state.page))window.ProductivitySuite?.stash();if(state.page==='memory')window.MemoryWorkbench?.stash();if(state.page==='search')window.ScanWorkbench?.stash();if(save)rememberForm();state.page=page;if(operation)state.operations[page]=operation;state.tablePage=0;state.filter='';render();}
function chooseOperation(operation){rememberForm();state.operations[state.page]=operation;state.tablePage=0;state.filter='';render();}
function defaultValue(f){if(f.value==='@address')return state.address;if(f.value==='@tid')return state.tid;if(f.value==='@pid')return state.pid || '';if(f.value==='@id')return state.lastId;return f.value;}
function rememberForm(){const form=$('#tool-form');if(!form)return;const operation=form.dataset.operation;state.forms[operation]={};for(const [key,value] of new FormData(form))state.forms[operation][key]=value;for(const input of form.querySelectorAll('input[type=checkbox]'))state.forms[operation][input.name]=input.checked;}
function fieldHTML(f,operation){const value=state.forms[operation]?.[f.key] ?? defaultValue(f);let control;if(f.kind==='select'){control=`<select name="${f.key}" id="f-${f.key}">${f.options.map(option=>{const [key,label]=Array.isArray(option)?option:[option,option];return `<option value="${esc(key)}" ${String(value)===String(key)?'selected':''}>${esc(label)}</option>`;}).join('')}</select>`;}else if(f.kind==='checkbox'){control=`<input type="checkbox" name="${f.key}" id="f-${f.key}" ${value===true || value==='true'?'checked':''}>`;}else if(['area','json'].includes(f.kind)){control=`<textarea name="${f.key}" id="f-${f.key}" spellcheck="false">${esc(value)}</textarea>`;}else{control=`<input name="${f.key}" id="f-${f.key}" value="${esc(value)}" autocomplete="off" ${f.kind==='number'?'inputmode="numeric"':''}>`;}return `<label class="${['area','json'].includes(f.kind)?'wide':''}">${esc(f.label)}${control}</label>`;}

let visits=[],visitIndex=-1,visiting=false;
function clearVisits(){visits=[];visitIndex=-1;drawVisits();}
function recordVisit(value,destination){if(visiting||!state.pid||!value)return;const page=destination||(['memory','disassembly','search','structures','wide'].includes(state.page)?state.page:'memory');if(visits[visitIndex]?.address===value&&visits[visitIndex]?.page===page)return;visits=visits.slice(0,visitIndex+1);visits.push({address:value,page});if(visits.length>100)visits.shift();visitIndex=visits.length-1;drawVisits();}
function drawVisits(){const back=document.querySelector('#address-back'),forward=document.querySelector('#address-forward');if(back)back.disabled=visitIndex<=0;if(forward)forward.disabled=visitIndex>=visits.length-1;}
function visit(delta){if(state.busy)return toast('현재 요청을 기다리세요',true);const index=visitIndex+delta;if(index<0||index>=visits.length)return;visiting=true;try{visitIndex=index;applyAddress(visits[index].address);updateTarget();persist();navigate(visits[index].page);}finally{visiting=false;drawVisits();}}
