function suiteContext(){return {root:$('#main-content'),pid:state.pid,address:state.address,currentPid:()=>state.pid,api,toast,download,isBusy:()=>state.busy,setBusy:value=>{state.busy=value;},navigate,route:(value,page)=>{applyAddress(value,page);updateTarget();persist();navigate(page);},onAddress:value=>{applyAddress(value);updateTarget();persist();},capture:async()=>{const memory=window.MemoryWorkbench?.exportState()||{},wide=window.WideMemory?.exportState()||{},scan=window.ScanWorkbench?.exportState()||{},disassembly=window.DisassemblyWorkbench?.exportState()||{},suite=window.ProductivitySuite?.exportState()||{};const symbols=await api('/api/studio/symbols');const addresses=[];for(const [i,item] of (suite.timeline?.items||[]).entries())addresses.push({key:'timeline:'+i,address:item.address});for(const [i,v] of visits.entries())addresses.push({key:'visit:'+i,address:v.address});if(wide.address)addresses.push({key:'wide',address:wide.address});if(wide.schemaAddress)addresses.push({key:'wide-schema',address:wide.schemaAddress});if(memory.address)addresses.push({key:'memory',address:memory.address});if(disassembly.address)addresses.push({key:'disassembly',address:disassembly.address});if(suite.base)addresses.push({key:'structure',address:suite.base});for(const [i,row] of (scan.saved||[]).entries())addresses.push({key:'saved:'+i,address:row.address});for(const [i,row] of state.bookmarks.filter(b=>b.pid===state.pid).entries())addresses.push({key:'bookmark:'+i,address:row.address});return {memory,wide,scan,disassembly,suite,navigation:{visits,visitIndex},addresses,definitions:suite.definitions,symbols:symbols.results,notes:suite.notes,forms:state.forms,operations:state.operations,page:state.page,bookmarks:state.bookmarks.filter(b=>b.pid===state.pid)};},restore:async r=>{window.ScanWorkbench?.reset();state.forms=r.identity===r.project.identity?r.state.forms||{}:{};state.operations=r.state.operations||{};const m={...(r.state.memory||{}),address:r.resolved.memory||''};window.MemoryWorkbench?.importState(m);window.WideMemory?.importState({...r.state.wide,address:r.resolved.wide||'',schemaAddress:r.resolved['wide-schema']||''});window.DisassemblyWorkbench?.importState({...r.state.disassembly,address:r.resolved.disassembly||''});window.ProductivitySuite?.importState({...r.state.suite,timeline:r.timeline||null,definitions:r.state.definitions,notes:r.state.notes,base:r.resolved.structure||''});window.ScanWorkbench?.importState({...r.state.scan,pid:state.pid,session:r.state.scan_restored?r.state.scan.session:'',saved:(r.state.scan.saved||[]).map((row,i)=>({...row,address:r.resolved['saved:'+i],frozen:false})).filter(row=>row.address)});state.bookmarks=(r.state.bookmarks||[]).map((b,i)=>({...b,pid:state.pid,address:r.resolved['bookmark:'+i]})).filter(b=>b.address);state.address=r.resolved.memory||r.resolved.structure||r.resolved.disassembly||'';visits=(r.state.navigation?.visits||[]).map((v,i)=>({...v,address:r.resolved['visit:'+i]})).filter(v=>v.address);visitIndex=visits.length-1;drawVisits();updateTarget();persist();}};}
function render(){const page=pageInfo();$('#page-title').textContent=page[1];$('#breadcrumb').textContent=state.pid?`PID ${state.pid} / ${state.name}`:'WORKSPACE';const search=$('#tool-search').value.toLowerCase();$('#navigation').innerHTML=PAGES.filter(p=>!search || p[1].toLowerCase().includes(search) || p[3].some(op=>TOOLS[op].label.toLowerCase().includes(search))).map(p=>`<button data-page="${p[0]}" class="${state.page===p[0]?'active':''}"><i>${p[2]}</i>${p[1]}</button>`).join('');for(const button of $('#navigation').querySelectorAll('button'))button.onclick=()=>navigate(button.dataset.page);if(state.page==='home'){renderHome();return;}if(['structures','projects','changes','timeline'].includes(state.page)){window.ProductivitySuite.render(suiteContext(),state.page);return;}if(state.page==='allocation'&&window.MemoryAllocation){window.MemoryAllocation.render(suiteContext());return;}if(state.page==='wide'&&window.WideMemory){window.WideMemory.render(suiteContext());return;}if(state.page==='memory'&&window.MemoryWorkbench){window.MemoryWorkbench.render({root:$('#main-content'),pid:state.pid,address:state.address,currentPid:()=>state.pid,api,toast,isBusy:()=>state.busy,setBusy:value=>{state.busy=value;},onAddress:value=>{applyAddress(value);updateTarget();persist();},route:(value,page)=>{applyAddress(value,page);updateTarget();persist();navigate(page);},rawTools:()=>navigate('memory_raw','read'),saveAddress:async(value,name)=>{if(state.busy)throw Error('현재 요청이 완료된 후 다시 보관하세요');const pid=state.pid;state.busy=true;try{await window.ScanWorkbench.saveExternal({root:$('#main-content'),pid,currentPid:()=>state.pid,api,toast,setBusy:value=>{state.busy=value;}},{address:value,data_type:'aob',width:1,description:name});toast('메모리 스캔의 보관 목록에 HEX 1바이트로 추가했습니다');}finally{state.busy=false;}}});return;}if(state.page==='search'&&window.ScanWorkbench){window.ScanWorkbench.render({root:$('#main-content'),pid:state.pid,address:state.address,currentPid:()=>state.pid,api,toast,download,isBusy:()=>state.busy,setBusy:value=>{state.busy=value;if(!value&&state.page!=='search'){rememberForm();render();}},route:(value,operation)=>{applyAddress(value);updateTarget();persist();if(operation==='disassemble_address')navigate('disassembly');else if(operation==='structure')navigate('structures');else routeRow({address:value},operation);}});return;}if(state.page==='dll'&&window.DllWorkbench){window.DllWorkbench.render({root:$('#main-content'),pid:state.pid,currentPid:()=>state.pid,api,toast,download,isBusy:()=>state.busy,setBusy:value=>{state.busy=value;}});return;}if(state.page==='disassembly'&&window.DisassemblyWorkbench){window.DisassemblyWorkbench.render({root:$('#main-content'),pid:state.pid,address:state.address,currentPid:()=>state.pid,api,toast,download,isBusy:()=>state.busy,setBusy:value=>{state.busy=value;},onAddress:value=>{applyAddress(value);updateTarget();persist();}});return;}const operation=currentOperation(), config=TOOLS[operation];$('#main-content').innerHTML=`<div class="operation-tabs">${page[3].map(op=>`<button data-operation="${op}" class="${op===operation?'active':''}">${TOOLS[op].label}</button>`).join('')}</div><section class="card"><div class="card-head"><div><h2>${config.label}</h2><p>${config.description}</p></div><span class="chip">${state.pid?`PID ${state.pid}`:'대상을 선택하세요'}</span></div><form id="tool-form" data-operation="${operation}"><div class="fields">${config.fields.map(f=>fieldHTML(f,operation)).join('')}</div><div class="actions"><button type="submit" id="execute-tool" ${state.busy?'disabled':''}>${config.queued?'작업 큐에서 실행':'실행'}</button>${operation==='write'?'<button type="button" id="import-binary" class="secondary">바이너리 가져오기</button>':''}<span id="busy-note" class="busy-note">${state.busy?'진행 중인 요청을 기다리는 중…':''}</span><span class="hint">${config.queued?'검색은 백그라운드에서 실행됩니다. 작업 큐에서 결과와 취소 상태를 확인하세요.':'주소는 0x 형식 또는 10진수로 입력할 수 있습니다.'}</span></div></form></section><div id="special-content"></div><section id="result-section"></section>`;$('#tool-form').onsubmit=e=>{e.preventDefault();executeTool();};for(const button of $('.operation-tabs').querySelectorAll('button'))button.onclick=()=>chooseOperation(button.dataset.operation);if($('#import-binary'))$('#import-binary').onclick=()=>$('#binary-file').click();renderResult();loadSpecial();}
function renderHome(){const status=state.status || {};$('#main-content').innerHTML=`<div class="metrics"><div class="metric"><small>드라이버 연결</small><strong>${status.success?'연결됨':'확인 중'}</strong></div><div class="metric"><small>브라우저 작업</small><strong>${Object.keys(TOOLS).length}개</strong></div><div class="metric"><small>지원 IOCTL 연결</small><strong>34 / 34</strong></div><div class="metric"><small>드라이버 처리 요청</small><strong>${esc(status.total_ioctl_requests ?? '—')}</strong></div></div><div class="card"><div class="card-head"><div><h2>주소 하나에서 시작하는 작업 공간</h2><p>대상을 선택하고 메모리를 검색·편집·비교하세요. 결과의 주소와 TID를 다른 도구로 바로 보낼 수 있습니다.</p></div><button id="home-target" class="secondary">대상 선택</button></div><div class="cards">${[['memory','메모리 편집','읽기 · 형식별 쓰기 · 바이너리 덤프'],['search','메모리 스캔','New · Next · Unknown · 문자열 · AOB'],['analysis','변경 분석','스냅샷 비교 · 패치 복구 · 포인터 · 구조체'],['threads','스레드 제어','레지스터 편집 · 우선순위 · CPU 지정'],['modules','모듈 살펴보기','커널 메모리 맵 · 모듈 경로 · PE 섹션'],['jobs','반복 작업 구성','JSON 시나리오 · 결과 참조 · 작업 큐']].map(([page,title,desc])=>`<button data-open-page="${page}">${title}<small>${desc}</small></button>`).join('')}</div></div><div class="split"><section class="card"><div class="card-head"><h2>주소 북마크</h2><button id="bookmark-add" class="small secondary">현재 주소 저장</button></div><div class="bookmarks">${state.bookmarks.length?state.bookmarks.map((b,i)=>`<div class="bookmark"><div><strong>${esc(b.name)}</strong><div class="mono subtle">PID ${esc(b.pid)} · ${esc(b.address)}</div></div><div><button class="small secondary" data-bookmark="${i}">사용</button> <button class="small secondary" data-bookmark-delete="${i}">삭제</button></div></div>`).join(''):'<div class="empty">현재 주소를 저장해 빠르게 다시 찾으세요.</div>'}</div><div class="actions"><button id="workspace-export" class="secondary small">북마크 내보내기</button><button id="workspace-import" class="secondary small">북마크 가져오기</button></div></section><section class="card"><h2>연결된 기능</h2><p>프로세스 정보, 메모리 관리, 검색, 모듈, 스레드, 중단점, DLL 기능을 사용할 수 있습니다.</p><div class="notice">프로세스·이미지 알림 콜백은 제거되었습니다. 스레드 종료도 사용 범위에서 제외합니다.</div><p class="subtle">스냅샷과 패치 이력은 서버 세션에 보관됩니다. 브라우저 북마크는 로컬에 저장되며, 가져오기가 메모리 쓰기나 Freeze를 자동 실행하지 않습니다.</p><button id="home-capabilities" class="secondary">전체 연결 기능 확인</button></section></div>`;$('#home-target').onclick=openProcess;for(const button of document.querySelectorAll('[data-open-page]'))button.onclick=()=>navigate(button.dataset.openPage);$('#home-capabilities').onclick=()=>navigate('history');$('#bookmark-add').onclick=()=>{if(!state.pid || !state.address)return toast('프로세스와 주소를 먼저 선택하세요',true);state.bookmarks.push({pid:state.pid,address:state.address,name:`${state.name} ${state.address}`});state.bookmarks=state.bookmarks.slice(-100);persist();renderHome();};for(const button of document.querySelectorAll('[data-bookmark]'))button.onclick=()=>{const b=state.bookmarks[Number(button.dataset.bookmark)];if(state.busy)return toast('현재 요청이 완료된 후 대상을 변경하세요',true);if(state.pid!==b.pid){state.forms={};state.results={};state.lastId='';state.tid='';}window.ProductivitySuite?.reset();clearVisits();window.MemoryWorkbench?.reset();window.WideMemory?.reset();window.MemoryAllocation?.reset();window.ScanWorkbench?.reset();window.DisassemblyWorkbench?.reset();window.DllWorkbench?.reset(b.pid);state.pid=b.pid;state.name=b.name;applyAddress(b.address);persist();updateTarget();navigate('memory','read',false);};for(const button of document.querySelectorAll('[data-bookmark-delete]'))button.onclick=()=>{state.bookmarks.splice(Number(button.dataset.bookmarkDelete),1);persist();renderHome();};$('#workspace-export').onclick=()=>download(JSON.stringify({version:1,pid:state.pid,name:state.name,address:state.address,tid:state.tid,bookmarks:state.bookmarks},null,2),'kernel-workspace.json','application/json');$('#workspace-import').onclick=()=>$('#workspace-file').click();}
function formArgs(){const config=TOOLS[currentOperation()],form=$('#tool-form'),args={pid:state.pid};for(const f of config.fields){const control=form.elements.namedItem(f.key);let value=f.kind==='checkbox'?control.checked:control.value;if(f.kind==='json'){value=JSON.parse(value);}else if(f.kind==='number' || (f.kind==='select' && typeof f.value==='number')){value=Number(value);if(!Number.isSafeInteger(value))throw Error(`${f.label}: 정수를 입력하세요`);}if(f.key==='expected' && !value)continue;if(currentOperation()==='watch_update' && f.key==='value' && value==='')continue;args[f.key]=value;}return args;}
async function executeTool(){if(state.busy)return;const operation=currentOperation(),config=TOOLS[operation];try{const args=formArgs();if(!state.pid && !['status','monitor','snapshot_list','patch_list','hwbp_list','map_list','map_delete','snapshot_delete','patch_delete','dump_list'].includes(operation))throw Error('대상 프로세스를 먼저 선택하세요');rememberForm();state.busy=true;$('#execute-tool').disabled=true;$('#busy-note').textContent='요청 진행 중…';const originatingPage=state.page;let result;if(config.dumpMode){result=await api('/api/studio/dumps',{...args,mode:config.dumpMode});if(result.success){toast('덤프를 등록했습니다. 아래 목록에서 진행률을 확인하세요.');await refreshDumps();}}else if(config.queued){const submitted=await api('/api/studio/jobs',{operation,args});toast('작업을 큐에 등록했습니다');result=await waitJob(submitted.job_id,originatingPage);}else if(config.endpoint){let path=config.endpoint;const body={...args};if(['scan_next','scan_results','scan_reset','watch_update','watch_freeze','watch_remove'].includes(operation))delete body.pid;if(config.method==='GET'){path+='?'+new URLSearchParams(body);result=await api(path);}else{if(operation==='inspect')body.size=16;result=await api(path,body);}}else{result=await api('/api/studio/execute',{operation,args});}if(operation==='dump' && result.success)download(bytesFromHex(result.data_hex),`memory_${state.pid}_${args.address}.bin`,'application/octet-stream');state.results[originatingPage]={operation,args,result};if(result.snapshot_id || result.patch_id || result.breakpoint_id || result.item_id || result.map_id)applyId(result.snapshot_id || result.patch_id || result.breakpoint_id || result.item_id || result.map_id);if(operation==='alloc' && result.success){state.address=result.allocated_address;updateTarget();persist();}if(['pointer_chain','resolve'].includes(operation) && result.success){state.address=result.address;updateTarget();persist();}if(originatingPage===state.page){state.tablePage=0;state.filter='';renderResult();}const good=result.success!==false;toast(good?'작업 완료':`실패: ${result.error || result.result_status || result.driver_response?.result_status || '반환 상태를 확인하세요'}`,!good);}catch(error){toast(error.message,true);state.results[state.page]={operation,args:{},result:{success:false,error:error.message}};renderResult();}finally{state.busy=false;if($('#execute-tool'))$('#execute-tool').disabled=false;if($('#busy-note'))$('#busy-note').textContent='';}}
async function waitJob(key,page){for(;;){await new Promise(resolve=>setTimeout(resolve,350));const job=await api(`/api/studio/jobs/${key}`);$('#footer-status').textContent=`${TOOLS[job.operation]?.label || job.operation} · ${job.state}`;if(['completed','failed','cancelled'].includes(job.state))return job.result || {success:false,cancelled:true};if(state.page==='jobs')loadSpecial();}}
function rowsFor(result){if(result.results)return result.results;if(result.items)return result.items;if(result.handles)return result.handles;if(result.threads)return result.threads;if(result.fields)return result.fields;if(result.events)return result.events;if(result.interpretations)return Object.entries(result.interpretations).map(([name,value])=>({name,value}));if(result.data_hex){const bytes=bytesFromHex(result.data_hex),base=BigInt(result.address || '0');const rows=[];for(let i=0;i<bytes.length;i+=16){const part=bytes.slice(i,i+16);rows.push({address:'0x'+(base+BigInt(i)).toString(16).toUpperCase(),bytes:Array.from(part).map(b=>b.toString(16).padStart(2,'0')).join(' ').toUpperCase(),ascii:Array.from(part).map(b=>b>=32&&b<127?String.fromCharCode(b):'.').join('')});}return rows;}if(result.basic)return ['basic','extended','token'].flatMap(group=>Object.entries(result[group]).map(([name,value])=>({group,name,value})));return Object.entries(result).filter(([,v])=>typeof v!=='object').map(([name,value])=>({name,value}));}
const labelMap={address:'주소',size:'크기',name:'이름',path:'경로',value:'값',type:'형식',text:'내용',encoding:'인코딩',thread_id:'TID',process_id:'PID',group:'분류',instruction:'명령어',operands:'피연산자',bytes:'바이트',before:'이전',after:'현재',offset:'오프셋',total:'전체',id:'ID',state:'상태',description:'설명',current_value:'현재 값',frozen:'고정',operation:'작업',status:'반환 상태',milliseconds:'시간 ms',ioctl:'IOCTL',priority:'우선순위',start_address:'시작 주소',image_name:'이미지',protect:'보호',time:'시간'};
function cellValue(value){if(value===true)return '✓';if(value===false)return '—';if(value && typeof value==='object')return JSON.stringify(value);return String(value ?? '');}
function renderResult(){const section=$('#result-section');if(!section)return;const saved=state.results[state.page];if(!saved){section.innerHTML='<div class="card empty"><strong>결과가 여기에 표시됩니다</strong>작업을 실행하거나 목록을 새로 고침하세요.</div>';return;}const result=saved.result;let rows=rowsFor(result);if(state.filter)rows=rows.filter(row=>JSON.stringify(row).toLowerCase().includes(state.filter.toLowerCase()));const total=rows.length,pageSize=50,pages=Math.max(1,Math.ceil(total/pageSize));state.tablePage=Math.min(state.tablePage,pages-1);const visible=rows.slice(state.tablePage*pageSize,(state.tablePage+1)*pageSize);const keys=Array.from(new Set(visible.flatMap(Object.keys))).slice(0,12);const hasAddress=visible.some(row=>row.address || row.start_address || row.found_address);const hasId=visible.some(row=>row.id);const hasThread=visible.some(row=>row.thread_id);const metas=Object.entries(result).filter(([key,value])=>['success','result_status','error_code','total','count','changed_bytes','bytes_written','verified','buffers_released','truncated','partial','max_hit','alignment','failed_chunks','failed_candidates','returned_count','verified_fields','snapshot_id','patch_id','breakpoint_id','breakpoint_count','decoded_bytes','requested_bytes','note','cancelled'].includes(key) && typeof value!=='object');section.innerHTML=`<div class="card ${result.success===false?'result-failure':'result-success'}"><div class="card-head"><h2>${TOOLS[saved.operation]?.label || '조회'} 결과</h2><span class="${result.success===false?'error':'ok'}">${result.success===false?'실패':'완료'}</span></div>${result.error?`<div class="notice error">${esc(result.error)} ${esc(result.driver_response?.result_status || '')}</div>`:''}<div class="result-meta">${metas.map(([key,value])=>`<span>${esc(labelMap[key] || key)}: <strong>${esc(cellValue(value))}</strong></span>`).join('')}</div><div class="result-toolbar"><input id="result-filter" aria-label="결과 필터" placeholder="결과에서 찾기" value="${esc(state.filter)}"><div><button id="export-csv" class="secondary small">CSV 내보내기</button> <button id="export-json" class="secondary small">JSON 내보내기</button></div></div><div class="table-wrap">${total?`<table><thead><tr>${keys.map(key=>`<th>${esc(labelMap[key] || key)}</th>`).join('')}${hasAddress || hasId || hasThread?'<th>다른 도구로 보내기</th>':''}${saved.operation==='watch_list'?'<th>고정 / 관리</th><th>변화 추세</th>':''}</tr></thead><tbody>${visible.map((row,index)=>`<tr>${keys.map(key=>`<td title="${esc(cellValue(row[key]))}" class="${key.includes('address') || key==='bytes'?'mono':''}">${esc(cellValue(row[key]))}</td>`).join('')}${hasAddress || hasId || hasThread?`<td><div class="table-actions">${row.address || row.start_address || row.found_address?`<button class="small secondary" data-row="${index}" data-route="read">Hex</button><button class="small secondary" data-row="${index}" data-route="watch_add">Watch</button><button class="small secondary" data-row="${index}" data-route="disassemble">분석</button>`:''}${row.thread_id?`<button class="small secondary" data-row="${index}" data-route="context">레지스터</button>`:''}${row.id?`<button class="small secondary" data-row="${index}" data-route="id">ID 사용</button>`:''}</div></td>`:''}${saved.operation==='watch_list'?`<td><button class="small ${row.frozen?'danger':'secondary'}" data-watch-freeze="${esc(row.id)}" data-frozen="${row.frozen?'false':'true'}">${row.frozen?'고정 해제':'값 고정'}</button> <button class="small secondary" data-watch-remove="${esc(row.id)}">삭제</button></td><td>${sparkline(row)}</td>`:''}</tr>`).join('')}</tbody></table>`:'<div class="empty">표시할 결과가 없습니다.</div>'}</div><div class="pagination"><span>${total.toLocaleString()}개 · ${state.tablePage+1} / ${pages} 페이지${result.truncated?' · 반환 상한 적용됨':''}</span><div><button id="previous-page" class="secondary small" ${state.tablePage===0?'disabled':''}>이전</button><button id="next-page" class="secondary small" ${state.tablePage>=pages-1?'disabled':''}>다음</button></div></div>${saved.operation==='context' && result.success?registerEditor(result):''}${result.allocations?.length?`<details open><summary>이 화면에서 할당한 영역</summary><pre>${esc(JSON.stringify(result.allocations,null,2))}</pre></details>`:''}<details><summary>전체 응답 보기</summary><pre>${esc(JSON.stringify(result,null,2))}</pre></details></div>`;$('#result-filter').oninput=e=>{const caret=e.target.selectionStart;state.filter=e.target.value;state.tablePage=0;renderResult();$('#result-filter').focus();$('#result-filter').setSelectionRange(caret,caret);};$('#export-csv').onclick=()=>download(toCSV(rows),`${saved.operation}.csv`,'text/csv;charset=utf-8');$('#export-json').onclick=()=>download(JSON.stringify(result,null,2),`${saved.operation}.json`,'application/json');$('#previous-page').onclick=()=>{state.tablePage--;renderResult();};$('#next-page').onclick=()=>{state.tablePage++;renderResult();};for(const button of section.querySelectorAll('[data-route]'))button.onclick=()=>routeRow(visible[Number(button.dataset.row)],button.dataset.route);for(const button of section.querySelectorAll('[data-watch-freeze]'))button.onclick=()=>watchAction('/api/watch/freeze',{id:button.dataset.watchFreeze,frozen:button.dataset.frozen==='true'});for(const button of section.querySelectorAll('[data-watch-remove]'))button.onclick=()=>watchAction('/api/watch/remove',{id:button.dataset.watchRemove});if($('#save-registers'))$('#save-registers').onclick=()=>saveCapturedRegisters(saved,result);}
async function saveCapturedRegisters(saved,result){
 if(state.busy)return;
 const registers={};for(const input of document.querySelectorAll('[data-register]'))if(input.value!==result[input.dataset.register])registers[input.dataset.register]=input.value;
 if(!Object.keys(registers).length)return toast('변경된 레지스터가 없습니다');
 const pid=Number(saved.args.pid),tid=Number(saved.args.tid),originatingPage=state.page;
 if(pid!==state.pid || tid!==Number(result.thread_id))return toast('캡처한 대상이 현재 선택과 다릅니다. 다시 조회하세요.',true);
 state.busy=true;if($('#save-registers'))$('#save-registers').disabled=true;if($('#execute-tool'))$('#execute-tool').disabled=true;
 if($('#busy-note'))$('#busy-note').textContent='레지스터 편집 요청 중…';
 try{
  const changed=await api('/api/studio/execute',{operation:'set_context',args:{pid,tid,registers}});
  if(changed.registers){state.results[originatingPage]={operation:'context',args:saved.args,result:{...changed.registers,success:changed.success,verified:changed.verified,error:changed.error,differences:changed.differences}};if(state.page===originatingPage)renderResult();}
  if(!changed.success)throw Error(changed.error || changed.result_status || '레지스터 편집 실패');
  toast('변경한 레지스터를 기록하고 검증했습니다');
 }catch(error){toast(error.message,true);}
 finally{state.busy=false;if($('#save-registers'))$('#save-registers').disabled=false;if($('#execute-tool'))$('#execute-tool').disabled=false;if($('#busy-note'))$('#busy-note').textContent='';}
}

function registerEditor(result){return `<details open><summary>레지스터 편집</summary><p class="subtle">변경된 필드만 기록합니다. 나머지 레지스터는 현재 값을 유지합니다.</p><div class="grid-values">${['rip','rsp','rbp','rax','rbx','rcx','rdx','rsi','rdi','r8','r9','r10','r11','r12','r13','r14','r15','eflags'].map(name=>`<label>${name.toUpperCase()}<input data-register="${name}" aria-label="${name.toUpperCase()}" value="${esc(result[name])}" spellcheck="false"></label>`).join('')}</div><div class="actions"><button id="save-registers">변경한 레지스터 기록</button></div></details>`;}
function applyId(value){state.lastId=value;for(const [operation,config] of Object.entries(TOOLS))if(config.fields.some(f=>f.key==='id')){state.forms[operation]??={};state.forms[operation].id=value;}}
function applyAddress(value,destination){recordVisit(value,destination);state.address=value;for(const [operation,config] of Object.entries(TOOLS))for(const f of config.fields)if(f.value==='@address'){state.forms[operation]??={};state.forms[operation][f.key]=value;}}
function routeRow(row,operation){rememberForm();if(row.address || row.start_address || row.found_address)applyAddress(row.address || row.start_address || row.found_address);if(row.thread_id){state.tid=String(row.thread_id);for(const [key,config] of Object.entries(TOOLS))if(config.fields.some(f=>f.key==='tid')){state.forms[key]??={};state.forms[key].tid=state.tid;}}if(row.id){applyId(row.id);if(operation==='id'){updateTarget();persist();toast('목록 ID를 선택했습니다. 복원·비교·제거 작업에서 사용할 수 있습니다.');render();return;}}updateTarget();persist();const page=PAGES.find(page=>page[3].includes(operation));if(page)navigate(page[0],operation,false);}
function bytesFromHex(hex){const clean=hex.replace(/\s/g,'');return Uint8Array.from(clean.match(/.{1,2}/g) || [],byte=>parseInt(byte,16));}
function download(content,name,type){const blob=new Blob([content],{type});const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=name;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function toCSV(rows){const keys=Array.from(new Set(rows.flatMap(Object.keys)));const quote=value=>'"'+cellValue(value).replaceAll('"','""')+'"';return '\ufeff'+[keys.map(quote).join(','),...rows.map(row=>keys.map(key=>quote(row[key])).join(','))].join('\r\n');}
function sparkline(row){const values=state.samples[row.id] || [];if(values.length<2)return '<span class="subtle">수집 중</span>';const minimum=Math.min(...values),maximum=Math.max(...values),range=maximum-minimum || 1;const points=values.map((value,index)=>`${index/(values.length-1)*90},${25-(value-minimum)/range*22}`).join(' ');return `<svg viewBox="0 0 95 28" class="sparkline" aria-label="값 변화 추세"><polyline points="${points}" fill="none" stroke="#5de0cb" stroke-width="1.5"/></svg>`;}
function dumpFileUrl(job,name){return `/api/studio/dumps/${encodeURIComponent(job.id)}/files/${encodeURIComponent(name)}`;}
function byteSize(value){return `${Number(value).toLocaleString()} B (${(Number(value)/1048576).toFixed(2)} MiB)`;}
async function refreshDumps(){
 const section=$('#special-content');if(!section || state.page!=='dumps')return;
 const result=await api('/api/studio/dumps');if(state.page!=='dumps' || section!==$('#special-content'))return;
 const labels={queued:'대기',running:'덤프 중',packaging:'ZIP 묶는 중',completed:'완료',cancelled:'중단됨',failed:'실패'};
 const modes={range:'범위 덤프',image:'이미지 하나',images:'전체 MEM_IMAGE'};
 section.innerHTML=`<section class="card"><div class="card-head"><h2>덤프 작업 / 다운로드</h2><span>2초마다 진행률 갱신</span></div><p class="subtle">프로세스는 계속 실행됩니다. 중단 후 이어쓰기에는 최초 대상의 신원이 일치해야 합니다. 0 채움은 아래 누락 구간에 표시됩니다.</p>${result.jobs.length?result.jobs.map(job=>`<article class="dump-job"><div class="card-head"><div><strong>PID ${esc(job.pid)} · ${esc(modes[job.mode] || job.mode)} · ${esc(labels[job.state] || job.state)}</strong><div class="mono subtle">${esc(job.id)}</div></div><span>${esc(job.progress_percent)}%</span></div><progress max="100" value="${esc(job.progress_percent)}" aria-label="덤프 진행률"></progress><p>${esc(byteSize(job.completed_bytes))} / ${esc(byteSize(job.total_bytes))} · 0 채움 ${esc(byteSize(job.zero_bytes))} · 커널 읽기 ${esc(job.read_requests)}회</p>${job.error?`<p class="error">${esc(job.error)}</p>`:''}<div class="actions">${['queued','running','packaging'].includes(job.state)?`<button class="secondary small" data-dump-action="cancel" data-dump-id="${esc(job.id)}">취소</button>`:''}${['failed','cancelled'].includes(job.state)?`<button class="secondary small" data-dump-action="resume" data-dump-id="${esc(job.id)}">이어쓰기</button>`:''}<a class="dump-download" download href="${dumpFileUrl(job,'manifest.json')}">기록 JSON</a>${job.state==='completed' && job.bundle?`<a class="dump-download" download href="${dumpFileUrl(job,job.bundle.name)}">전체 ZIP 다운로드</a>`:''}${!['queued','running','packaging'].includes(job.state)?`<button class="secondary small" data-dump-action="delete" data-dump-id="${esc(job.id)}">파일·이력 삭제</button>`:''}</div><div class="table-wrap"><table><thead><tr><th>파일 / 모듈</th><th>기준 주소</th><th>크기</th><th>SHA256 / 다운로드</th></tr></thead><tbody>${job.files.map(file=>`<tr><td>${esc(file.module)}<div class="subtle">${esc(file.name)}</div></td><td class="mono">${esc(file.address)}</td><td>${esc(byteSize(file.written))} / ${esc(byteSize(file.size))}</td><td>${file.sha256?`<div class="mono" title="${esc(file.sha256)}">${esc(file.sha256.slice(0,16))}…</div>`:''}${job.state==='completed'?`<a download href="${dumpFileUrl(job,file.name)}">바이너리 다운로드</a>`:''}</td></tr>`).join('')}</tbody></table></div>${job.holes.length?`<details><summary>누락 구간 ${job.holes.length}개</summary><pre>${esc(JSON.stringify(job.holes,null,2))}</pre></details>`:''}</article>`).join(''):'<div class="empty">등록한 덤프가 없습니다.</div>'}</section>`;
 for(const button of section.querySelectorAll('[data-dump-action]'))button.onclick=async()=>{try{button.disabled=true;const action=button.dataset.dumpAction,key=encodeURIComponent(button.dataset.dumpId);let response;if(action==='delete'){const r=await fetch(`/api/studio/dumps/${key}`,{method:'DELETE'});response=JSON.parse(await r.text());if(!r.ok)throw Error(response.detail || '삭제 실패');}else response=await api(`/api/studio/dumps/${key}/${action}`,{});if(response.success===false)throw Error(response.error || '덤프 요청 실패');await refreshDumps();toast(action==='cancel'?'취소를 요청했습니다':action==='resume'?'이어쓰기를 요청했습니다':'덤프 파일과 이력을 삭제했습니다');}catch(error){toast(error.message,true);button.disabled=false;}};
}
async function watchAction(path,data){try{const result=await api(path,data);if(result.success===false)throw Error(result.error || 'Watch 작업 실패');await refreshWatch();toast('Watch를 갱신했습니다');}catch(error){toast(error.message,true);}}
async function refreshWatch(){const result=await api('/api/watch/list');for(const row of result.items){const value=Number(row.current_value);if(Number.isFinite(value)){const samples=state.samples[row.id] || [];samples.push(value);state.samples[row.id]=samples.slice(-60);}}state.results.watch={operation:'watch_list',args:{},result:{success:true,...result}};if(state.page==='watch' && currentOperation()==='watch_list')renderResult();}
async function loadSpecial(){const section=$('#special-content');if(!section)return;try{if(state.page==='dumps'){await refreshDumps();}else if(state.page==='jobs'){const result=await api('/api/studio/jobs');section.innerHTML=`<div class="card"><div class="card-head"><h2>작업 큐</h2><span class="subtle">현재 IOCTL 완료 후 취소합니다</span></div><div class="table-wrap"><table><thead><tr><th>작업</th><th>상태</th><th>관리</th></tr></thead><tbody>${result.jobs.map(job=>`<tr><td>${esc(TOOLS[job.operation]?.label || job.operation)}<div class="subtle">${esc(job.id)}</div></td><td>${esc(job.state)}</td><td><button class="secondary small" data-job-result="${job.id}">결과</button> <button class="secondary small" data-job-cancel="${job.id}" ${['completed','failed','cancelled'].includes(job.state)?'disabled':''}>취소</button></td></tr>`).join('')}</tbody></table></div></div>`;for(const button of section.querySelectorAll('[data-job-result]'))button.onclick=async()=>{const job=await api(`/api/studio/jobs/${button.dataset.jobResult}`);state.results.jobs={operation:job.operation,args:{},result:job.result || {success:false,error:'작업이 아직 실행 중입니다'}};renderResult();};for(const button of section.querySelectorAll('[data-job-cancel]'))button.onclick=async()=>{await api(`/api/studio/jobs/${button.dataset.jobCancel}/cancel`,{});toast('취소를 요청했습니다');loadSpecial();};}else if(state.page==='history'){const [caps,history]=await Promise.all([api('/api/studio/capabilities'),api('/api/studio/history')]);section.innerHTML=`<div class="card"><h2>드라이버 기능 연결 ${caps.ioctls.length}개</h2><p>반환 목록 해제 기능은 각 도구에서 자동 사용합니다. 스레드 종료와 프로세스·이미지 알림 이벤트는 제거했습니다.</p><div class="table-wrap"><table><thead><tr><th>IOCTL</th><th>화면 / 처리</th><th>이 서버 호출 횟수</th></tr></thead><tbody>${caps.ioctls.map(item=>`<tr><td class="mono">${item.ioctl}</td><td>${esc(TOOLS[item.tool]?.label || item.tool)}</td><td>${history.counts[item.ioctl] || 0}</td></tr>`).join('')}</tbody></table></div></div>`;state.results.history={operation:'status',args:{},result:{success:true,results:history.results.slice().reverse()}};renderResult();}else if(state.page==='watch' && currentOperation()==='watch_list'){await refreshWatch();}}catch(error){toast(error.message,true);}}
async function refreshStatus(){try{state.status=await api('/api/studio/execute',{operation:'status',args:{}});$('#connection-dot').classList.toggle('connected',state.status.success===true);$('#connection-text').textContent=state.status.success?`연결됨 · v${state.status.major_version}.${state.status.minor_version}`:'드라이버 연결 실패';if(state.page==='home')renderHome();}catch{$('#connection-text').textContent='서버 연결 실패';$('#connection-dot').classList.remove('connected');}}
let processRequestId=0,processLoading=false,processError='',processMeta=null,processSelectionBusy=false,processSelectionError='';
function processControls(){for(const id of ['refresh-processes','process-range'])$('#'+id).disabled=processLoading || processSelectionBusy;$('#identify-target').disabled=processSelectionBusy;}
async function loadProcesses(){
 if(processLoading || processSelectionBusy)return;
 const requestId=++processRequestId;processLoading=true;processError='';processSelectionError='';processMeta=null;state.processes=[];processControls();renderProcesses();
 try{const result=await api(`/api/processes?max_pid=${Number($('#process-range').value)}&refresh=true`);
  if(requestId!==processRequestId || !$('#process-dialog').open)return;
  if(result.success===false || !Array.isArray(result.processes))throw Error(result.error || '프로세스 목록을 읽을 수 없습니다');
  state.processes=result.processes;processMeta=result;
 }catch(error){if(requestId!==processRequestId || !$('#process-dialog').open)return;processError=error.message;toast(error.message,true);}
 finally{if(requestId===processRequestId){processLoading=false;processControls();renderProcesses();}}
}
function openProcess(){if(state.busy)return toast('현재 요청이 완료된 후 대상을 변경하세요',true);if(processSelectionBusy)return toast('대상 확인이 완료된 후 다시 여세요',true);if($('#process-dialog').open)return;$('#process-search').value='';$('#process-dialog').showModal();$('#process-search').focus();loadProcesses();}
function renderProcesses(){
 const list=$('#process-list'),status=$('#process-status');list.setAttribute('aria-busy',String(processLoading));status.classList.toggle('error',Boolean(processError || processSelectionError));
 if(processLoading){status.textContent=processSelectionError || '커널에서 실행 중인 프로세스를 조회하는 중…';list.innerHTML='<div class="empty">프로세스 목록을 불러오는 중…</div>';return;}
 if(processError){status.textContent='목록 조회 실패 · 목록 새로 고침으로 다시 시도할 수 있습니다.';list.innerHTML=`<div class="empty error">${esc(processError)}</div>`;return;}
 const filter=$('#process-search').value.trim().toLowerCase();const rows=state.processes.filter(p=>String(p.pid).includes(filter)||String(p.name).toLowerCase().includes(filter));
 status.textContent=processSelectionError || `실행 중 ${state.processes.length}개 · 표시 ${rows.length}개 · 커널 조회 PID 4 ~ ${Number(processMeta?.max_pid || $('#process-range').value).toLocaleString()}${processMeta?.seconds!==undefined?` · ${processMeta.seconds}초`:''}${processMeta?.access_denied_count?` · 접근 불가 ${processMeta.access_denied_count}개`:''}. 범위 밖 PID는 조회 범위를 확장하거나 직접 입력하세요.`;
 list.innerHTML=rows.length?`<table><thead><tr><th>PID</th><th>프로세스</th><th>메모리 MB</th><th></th></tr></thead><tbody>${rows.map(p=>`<tr><td>${p.pid}</td><td title="${esc(p.image_path || p.name)}">${esc(p.name)}</td><td>${esc(p.memory_mb ?? '—')}</td><td><button class="small secondary" data-pid="${p.pid}" ${processSelectionBusy?'disabled':''}>선택</button></td></tr>`).join('')}</tbody></table>`:`<div class="empty">${filter?'검색 결과가 없습니다.':'조회 범위에서 실행 중인 프로세스를 찾지 못했습니다.'}</div>`;
 for(const button of list.querySelectorAll('button'))button.onclick=()=>{const p=state.processes.find(p=>p.pid===Number(button.dataset.pid));if(p)identifyProcess(p.pid,p.create_time);};
}
function processSelectionFailure(message){processSelectionError=message;renderProcesses();toast(message,true);}
async function identifyProcess(pid,expectedCreateTime){
 if(processSelectionBusy)return;
 if(state.busy)return processSelectionFailure('현재 요청을 기다리세요');
 if(!Number.isInteger(pid)||pid<=0||pid>0xffffffff)return processSelectionFailure('PID 범위를 확인하세요');
 const requestId=processRequestId;processSelectionBusy=true;processSelectionError='';processControls();renderProcesses();
 try{const info=await api(`/api/process/${pid}`);
  if(requestId!==processRequestId || !$('#process-dialog').open)return;
  if(!info.basic?.success||!info.extended?.success||info.basic.exit_status!==259||info.extended.exit_status!==259)throw Error('프로세스가 종료되었거나 조회할 수 없습니다. 목록을 새로 고침하세요.');
  if(expectedCreateTime && expectedCreateTime!=='0' && expectedCreateTime!==info.identity?.create_time)throw Error('목록 조회 후 PID가 다른 프로세스로 바뀌었습니다. 목록을 새로 고침하세요.');
  const canonicalPid=Number(info.basic.process_id);
  const name=(info.extended.image_file_name || info.basic.image_path || (canonicalPid===4?'System':`unknown (PID ${canonicalPid})`)).replaceAll('\\','/').split('/').at(-1);
  selectTarget(canonicalPid,name);
 }catch(error){if(requestId===processRequestId && $('#process-dialog').open)processSelectionFailure(error.message);}
 finally{processSelectionBusy=false;processControls();if($('#process-dialog').open)renderProcesses();}
}
$('#choose-process').onclick=openProcess;$('#close-process').onclick=()=>$('#process-dialog').close();$('#process-search').oninput=renderProcesses;
$('#process-dialog').onclose=()=>{++processRequestId;processLoading=false;processControls();};
$('#refresh-processes').onclick=loadProcesses;$('#process-range').onchange=loadProcesses;
$('#identify-target').onclick=()=>identifyProcess(Number($('#manual-pid').value));
$('#manual-pid').onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();$('#identify-target').click();}};
$('#tool-search').oninput=()=>render();
$('#global-address').onchange=e=>{rememberForm();applyAddress(e.target.value.trim());persist();render();};
$('#global-tid').onchange=e=>{rememberForm();state.tid=e.target.value.trim();persist();for(const fields of Object.values(state.forms))if('tid' in fields)fields.tid=state.tid;render();};
const MUTATIONS=new Set(['write','alloc','free','protect','copy','fill','restore','patch','undo','structure_write','set_context','suspend','resume','priority','affinity','hide','thread_batch','hwbp_set','hwbp_remove','dll','batch','watch_add','watch_update','watch_freeze','watch_remove','map_delete','snapshot_delete','patch_delete']);
$('#refresh-page').onclick=()=>{if(state.page==='allocation'){window.MemoryAllocation?.refresh();return;}if(state.page==='wide'){window.WideMemory?.refresh();return;}if(['structures','projects','changes','timeline'].includes(state.page)){window.ProductivitySuite.refresh();return;}if(state.page==='memory'){window.MemoryWorkbench?.refresh();return;}if(state.page==='search'){window.ScanWorkbench?.refresh();return;}if(state.page==='disassembly'){window.DisassemblyWorkbench?.refresh();return;}if(state.page==='dll'){document.querySelector('#dll-refresh')?.click();return;}refreshStatus();if(['jobs','history','watch','dumps'].includes(state.page))loadSpecial();else if(state.page!=='home'){if(MUTATIONS.has(currentOperation()))toast('이 작업은 실행 버튼으로 요청하세요.');else executeTool();}};
document.addEventListener('keydown',e=>{if(e.ctrlKey && e.key.toLowerCase()==='k'){e.preventDefault();$('#tool-search').focus();}});
$('#workspace-file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>1024*1024)throw Error('작업 공간 파일이 너무 큽니다');const data=JSON.parse(await file.text());if(data.version!==1 || !Array.isArray(data.bookmarks))throw Error('작업 공간 형식이 아닙니다');state.bookmarks=data.bookmarks.slice(0,100).filter(b=>Number.isSafeInteger(b.pid)&&typeof b.address==='string').map(b=>({pid:b.pid,address:b.address,name:String(b.name || '').slice(0,120)}));persist();render();toast('북마크를 가져왔습니다. 메모리 쓰기는 실행하지 않았습니다.');}catch(error){toast(error.message,true);}e.target.value='';};
$('#binary-file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;if(file.size>1024*1024)throw Error('바이너리는 최대 1MB입니다');const bytes=new Uint8Array(await file.arrayBuffer());$('#f-data_type').value='hex';$('#f-value').value=Array.from(bytes).map(x=>x.toString(16).padStart(2,'0')).join(' ');rememberForm();toast(`${file.size}바이트를 입력했습니다. 실행 버튼으로 기록하세요.`);}catch(error){toast(error.message,true);}e.target.value='';};
updateTarget();render();refreshStatus();
let periodic=false;
setInterval(async()=>{if(periodic || state.busy)return;periodic=true;try{await refreshStatus();if(['jobs','history','watch','dumps'].includes(state.page))await loadSpecial();}finally{periodic=false;}},2000);


